function columnsTopDown(root: TreeNode | null): number[][] {
  const cells: [number, number, number][] = [];
  const walk = (node: TreeNode | null, row: number, col: number) => {
    if (!node) return;
    cells.push([col, row, node.val]);
    walk(node.left, row + 1, col - 1);
    walk(node.right, row + 1, col + 1);
  };
  walk(root, 0, 0);
  cells.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const out: number[][] = [];
  let lastCol = NaN;
  for (const [col, , val] of cells) {
    if (col !== lastCol) { out.push([]); lastCol = col; }
    out[out.length - 1].push(val);
  }
  return out;
}

