            if not node:
                return
            cells.append((col, row, node.val))
            walk(node.left, row + 1, col - 1)
            walk(node.right, row + 1, col + 1)

        walk(root, 0, 0)
        cells.sort()
        out, last = [], None
        for col, _, val in cells:
            if col != last:
                out.append([])
                last = col
            out[-1].append(val)
        return out

