function columnsTopDown(root: TreeNode | null): number[][] {
  if (!root) return [];
  const columns = new Map<number, number[]>();
  let minCol = 0, maxCol = 0;
  let level: [TreeNode, number][] = [[root, 0]];
  while (level.length) {
    const spot = new Map<number, number[]>(); // column -> values on this row
    const next: [TreeNode, number][] = [];
    for (const [node, col] of level) {
      if (!spot.has(col)) spot.set(col, []);
      spot.get(col)!.push(node.val);
      if (node.left) next.push([node.left, col - 1]);
      if (node.right) next.push([node.right, col + 1]);
    }
    for (const [col, vals] of spot) {
      vals.sort((a, b) => a - b); // same row and column: smaller value first
      if (!columns.has(col)) columns.set(col, []);
      columns.get(col)!.push(...vals);
      minCol = Math.min(minCol, col);
      maxCol = Math.max(maxCol, col);
    }
    level = next;
  }
  const out: number[][] = [];
  for (let c = minCol; c <= maxCol; c++) out.push(columns.get(c)!);
  return out;
}

