class Solution:
    def columnsTopDown(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        columns = defaultdict(list)
        level = [(root, 0)]
        while level:
            spot = defaultdict(list)  # column -> values on this row
            nxt = []
            for node, col in level:
                spot[col].append(node.val)
                if node.left:
                    nxt.append((node.left, col - 1))
                if node.right:
                    nxt.append((node.right, col + 1))
            for col, vals in spot.items():
                columns[col].extend(sorted(vals))  # same row and column: smaller value first
            level = nxt
        return [columns[c] for c in range(min(columns), max(columns) + 1)]

